import { Component, Element, Prop, h } from "@stencil/core";

/**
 * @since 2.0
 * @status stable
 *
 * @slot - The menu label's content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-menu-label",
	styleUrl: "menu-label.scss",
	shadow: true,
})
export class MenuLabel {
	@Element() host: HTMLHbrMenuLabelElement;
	/** Menu label size */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** Menu label used in left side nav */
	@Prop() nav = false;

	render() {
		const isInShellNav = !!this.host.closest("hbr-shell-nav");
		return (
			<div
				part="base"
				class={{
					"menu-label": true,
					"menu-label--nav": this.nav,
					"menu-label--shell-nav": isInShellNav,
					[`menu-label--${this.size}`]: true,
				}}
			>
				<slot />
			</div>
		);
	}
}
